INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001380190','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001380190","revision":1,"targetId":"80000000-0000-4000-8000-000000013819","prompt":"In den ersten Monaten der neuen Stelle befindet sie sich noch in der ___.","instruction":{"en":"Choose the expression that best completes the sentence.","de":"Wähle den Ausdruck, der den Satz am besten ergänzt."},"hint":{"en":"This is the initial period in which the new job is being tried out.","de":"Gemeint ist die anfängliche Erprobungsphase im neuen Job."},"slots":[{"id":"answer","label":"Ausdruck","options":[{"id":"0","text":"Mittagspause"},{"id":"1","text":"Elternzeit"},{"id":"2","text":"Probezeit"},{"id":"3","text":"Rente"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"answer","optionId":"2"}]}],"explanation":{"en":"Probezeit is an initial trial period in an employment relationship.","de":"Probezeit bezeichnet eine anfängliche Erprobungsphase im Arbeitsverhältnis."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"In den ersten Monaten der neuen Stelle befindet sie sich noch in der Probezeit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1842 (b2fb880b0984f32fb299d4d14c90e972154fb7bced25b97da18e77b656c6d08b), 2026-10-29. Inherited example sentences not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
