INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001380191','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001380191","revision":1,"targetId":"80000000-0000-4000-8000-000000013819","prompt":"Im Vertrag steht: „Die Probezeit dauert sechs Monate.“ Was bezeichnet Probezeit?","instruction":{"en":"Read the German situation and choose the one correct answer.","de":"Lies die deutsche Situation und wähle die einzige richtige Antwort."},"hint":{"en":"The word names a phase at the beginning, not a legal consequence.","de":"Das Wort bezeichnet eine Anfangsphase, keine Rechtsfolge."},"options":[{"id":"0","text":"eine anfängliche Erprobungsphase"},{"id":"1","text":"die gesamte Beschäftigungsdauer"},{"id":"2","text":"den jährlichen Urlaub"},{"id":"3","text":"die Kündigung selbst"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Probezeit names the agreed initial trial phase; the example makes no claim about dismissal rights.","de":"Probezeit bezeichnet die vereinbarte anfängliche Erprobungsphase; daraus wird hier keine Kündigungsregel abgeleitet."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Probezeit ist eine anfängliche Erprobungsphase.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L1842 (b2fb880b0984f32fb299d4d14c90e972154fb7bced25b97da18e77b656c6d08b), 2026-10-29. Inherited example sentences not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
