INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001390000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001390000","revision":1,"targetId":"80000000-0000-4000-8000-000000013900","prompt":"Wegen fehlender Bauteile musste die ___ der Fahrräder an der Montagelinie stoppen.","instruction":{"en":"Choose the word that best completes the German sentence.","de":"Wähle das Wort, das den deutschen Satz am besten ergänzt."},"hint":{"en":"The assembly line cannot manufacture bicycles without parts.","de":"Ohne Bauteile kann die Montagelinie keine Fahrräder herstellen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Auslieferung"},{"id":"1","text":"Werbung"},{"id":"2","text":"Produktion"},{"id":"3","text":"Bestellung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"2"}]}],"explanation":{"en":"Produktion is the process of manufacturing goods.","de":"Produktion bezeichnet die Herstellung von Waren."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wegen fehlender Bauteile musste die Produktion der Fahrräder an der Montagelinie stoppen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1845 (a13ea95c9d30ce1ed2da2538dba64677a627cec48dcf120341659d4fbc4a9c7f), 2026-10-29. No inherited example sentence copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
