INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001390001','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001390001","revision":1,"targetId":"80000000-0000-4000-8000-000000013900","prompt":"In einer Fabrik werden täglich fünfhundert Fahrräder hergestellt. Wie heißt dieser Vorgang?","instruction":{"en":"Read the German situation and choose the one correct interpretation.","de":"Lies die deutsche Situation und wähle die einzige richtige Deutung."},"hint":{"en":"Focus on making the bicycles, not moving or selling them.","de":"Es geht um das Herstellen, nicht um den Verkauf."},"options":[{"id":"0","text":"Produktion"},{"id":"1","text":"Verkauf"},{"id":"2","text":"Transport"},{"id":"3","text":"Reklamation"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The making of goods in a factory is Produktion.","de":"Die Herstellung von Waren in einer Fabrik heißt Produktion."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Herstellung der Fahrräder ist die Produktion.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1845 (a13ea95c9d30ce1ed2da2538dba64677a627cec48dcf120341659d4fbc4a9c7f), 2026-10-29. No inherited example sentence copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
